#ifndef KERNEL_H
#define KERNEL_H

#include "ap_fixed.h"
#include "ap_int.h"

// ── Input 0: A  (complex, 10×10) ──────────────────────────────────────────
// bits=22, signed=1  → bits_per_component = 23, fraction=0
typedef ap_fixed<23, 23> in0_scalar_t;
struct in0_t { in0_scalar_t re, im; };
#define DIM_IN0_0 10
#define DIM_IN0_1 10

// ── Input 1: max_iter  (scalar, unsigned 16-bit) ───────────────────────────
// bits=16, signed=0  → bits_per_component = 16, fraction=0
typedef ap_fixed<16, 16> in1_t;

// ── Output 0: eigenvalues  (complex, length 10) ───────────────────────────
// bits=22, signed=1  → bits_per_component = 23, fraction=0
typedef ap_fixed<23, 23> out0_scalar_t;
struct out0_t { out0_scalar_t re, im; };
#define DIM_OUT0_0 10

// ── Output 1: eigenvectors  (complex, 10×10) ──────────────────────────────
// bits=22, signed=1  → bits_per_component = 23, fraction=20
typedef ap_fixed<23, 3> out1_scalar_t;
struct out1_t { out1_scalar_t re, im; };
#define DIM_OUT1_0 10
#define DIM_OUT1_1 10

// ── Output 2: ite  (scalar, unsigned 16-bit) ──────────────────────────────
// bits=16, signed=0  → bits_per_component = 16, fraction=0
typedef ap_fixed<16, 16> out2_t;

// ── Top-level kernel ──────────────────────────────────────────────────────
void kernel_top(
    in0_t  in0[DIM_IN0_0][DIM_IN0_1],
    in1_t  in1,
    out0_t out0[DIM_OUT0_0],
    out1_t out1[DIM_OUT1_0][DIM_OUT1_1],
    out2_t *out2
);

#endif // KERNEL_H

