#include "kernel.h"
#include "ap_fixed.h"

// ── Internal precision ────────────────────────────────────────────────────
// Use wider fixed-point for internal arithmetic (integer + 20 fractional bits)
typedef ap_fixed<48, 24> fx_t;   // general accumulator
typedef ap_fixed<48, 24> fxc_t;  // same for complex components

// ── Compile-time constants ────────────────────────────────────────────────
static const int  N          = 10;
// 1e-8 represented in fx_t  (threshold for convergence)
// fx_t has 24 fractional bits → 2^-24 ≈ 6e-8, use 2^-23 ≈ 1.2e-7 as safe threshold
// We compare magnitudes as integers to avoid transcendental overhead.
// threshold_sq = (1e-8)^2; since fraction=20 on output we use 1>>23 conservatively.

// ── Tiny cordic / polynomial helpers ─────────────────────────────────────

// Approximate sqrt(x) for x >= 0 using Newton-Raphson (4 iterations)
// x is in fx_t
static fx_t fx_sqrt(fx_t x) {
#pragma HLS INLINE
    if (x <= fx_t(0)) return fx_t(0);
    // Initial guess: shift right by half (bit-level approx is tricky with ap_fixed,
    // so we use a warm-start of 1 then iterate)
    fx_t r = fx_t(1);
    // 6 Newton-Raphson iterations: r = (r + x/r) / 2
    for (int i = 0; i < 6; i++) {
#pragma HLS UNROLL
        if (r == fx_t(0)) break;
        fx_t nr = (r + x / r);
        // divide by 2
        r = nr >> 1;
    }
    return r;
}

// Approximate |z| = sqrt(re^2 + im^2)
static fx_t cx_abs(fx_t re, fx_t im) {
#pragma HLS INLINE
    fx_t r2 = re * re + im * im;
    return fx_sqrt(r2);
}

// arctan approximation using minimax polynomial (range reduced to [-1,1])
// Good to ~5 ULPs in the range.
static fx_t fx_atan_unit(fx_t x) {
#pragma HLS INLINE
    // |x| <= 1  →  atan(x) ≈ x*(a0 + x^2*(a1 + x^2*(a2 + x^2*a3)))
    // Coefficients from Cody & Waite:
    // a0= 1, a1=-1/3, a2=1/5, a3=-1/7, a4=1/9  (truncated Taylor)
    // Use 5-term Taylor for reasonable precision:
    fx_t x2 = x * x;
    fx_t acc = fx_t(0);
    // Horner: a0 + x2*(a1 + x2*(a2 + x2*(a3 + x2*a4)))
    // a4 = 1/9, a3 = -1/7, a2 = 1/5, a1 = -1/3, a0 = 1
    acc = fx_t(0);
    // 1/9 ≈ 0.111111
    acc = fx_t(0.111111);
    // -1/7 ≈ -0.142857
    acc = fx_t(-0.142857) + x2 * acc;
    // 1/5 = 0.2
    acc = fx_t(0.2) + x2 * acc;
    // -1/3 ≈ -0.333333
    acc = fx_t(-0.333333) + x2 * acc;
    // 1
    acc = fx_t(1) + x2 * acc;
    return x * acc;
}

// atan2(y, x) using range reduction
static fx_t fx_atan2(fx_t y, fx_t x) {
#pragma HLS INLINE
    // pi/2 ≈ 1.5707963
    const fx_t PI_2 = fx_t(1.5707963);
    const fx_t PI   = fx_t(3.1415927);

    fx_t ay = (y < fx_t(0)) ? -y : y;
    fx_t ax = (x < fx_t(0)) ? -x : x;

    fx_t angle;
    if (ax == fx_t(0) && ay == fx_t(0)) return fx_t(0);

    if (ax >= ay) {
        fx_t t = ay / ax;
        angle = fx_atan_unit(t);
    } else {
        fx_t t = ax / ay;
        angle = PI_2 - fx_atan_unit(t);
    }

    // quadrant correction
    if (x < fx_t(0)) {
        angle = PI - angle;
    }
    if (y < fx_t(0)) {
        angle = -angle;
    }
    return angle;
}

// cos/sin via Taylor (range [-pi, pi])
static void fx_cos_sin(fx_t theta, fx_t &c, fx_t &s) {
#pragma HLS INLINE
    // Range-reduce theta to [-pi, pi] (assume already in range from atan)
    // cos: 1 - x^2/2 + x^4/24 - x^6/720 + x^8/40320
    // sin: x - x^3/6 + x^5/120 - x^7/5040 + x^9/362880
    fx_t x2 = theta * theta;
    fx_t x3 = x2 * theta;
    fx_t x4 = x2 * x2;
    fx_t x5 = x4 * theta;
    fx_t x6 = x4 * x2;
    fx_t x7 = x6 * theta;
    fx_t x8 = x4 * x4;
    fx_t x9 = x8 * theta;

    c = fx_t(1)
      - x2  * fx_t(0.5)
      + x4  * fx_t(0.041666667)     // 1/24
      - x6  * fx_t(0.001388889)     // 1/720
      + x8  * fx_t(0.000024802);    // 1/40320

    s = theta
      - x3  * fx_t(0.166666667)     // 1/6
      + x5  * fx_t(0.008333333)     // 1/120
      - x7  * fx_t(0.000198413)     // 1/5040
      + x9  * fx_t(0.000002756);    // 1/362880
}

// ── Complex matrix helpers ────────────────────────────────────────────────
struct cx_t {
    fx_t re, im;
};

static cx_t cx_add(cx_t a, cx_t b) {
#pragma HLS INLINE
    cx_t r; r.re = a.re + b.re; r.im = a.im + b.im; return r;
}

static cx_t cx_mul(cx_t a, cx_t b) {
#pragma HLS INLINE
    cx_t r;
    r.re = a.re * b.re - a.im * b.im;
    r.im = a.re * b.im + a.im * b.re;
    return r;
}

static cx_t cx_conj(cx_t a) {
#pragma HLS INLINE
    cx_t r; r.re = a.re; r.im = -a.im; return r;
}

// ── Working buffers (static to avoid stack pressure) ─────────────────────
static cx_t A_buf[N][N];
static cx_t V_buf[N][N];

// Temporary for matrix multiply
static cx_t tmp1[N][N];   // U^H * A
static cx_t tmp2[N][N];   // (U^H * A) * U
static cx_t tmp3[N][N];   // V * U

// ── Top-level kernel ──────────────────────────────────────────────────────
void kernel_top(
    in0_t  in0[DIM_IN0_0][DIM_IN0_1],
    in1_t  in1,
    out0_t out0[DIM_OUT0_0],
    out1_t out1[DIM_OUT1_0][DIM_OUT1_1],
    out2_t *out2
)
{
#pragma HLS INTERFACE ap_ctrl_hs port=return
#pragma HLS INTERFACE ap_memory  port=in0
#pragma HLS INTERFACE ap_memory  port=out0
#pragma HLS INTERFACE ap_memory  port=out1

    // ── Copy input A into working buffer ──────────────────────────────────
    INIT_A:
    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            A_buf[i][j].re = (fx_t)in0[i][j].re;
            A_buf[i][j].im = (fx_t)in0[i][j].im;
        }
    }

    // ── Initialise V = I ──────────────────────────────────────────────────
    INIT_V:
    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            V_buf[i][j].re = (i == j) ? fx_t(1) : fx_t(0);
            V_buf[i][j].im = fx_t(0);
        }
    }

    int max_iter_val = (int)in1;
    int last_z = 0;

    // ── Main Jacobi loop ──────────────────────────────────────────────────
    JACOBI_LOOP:
    for (int z = 0; z < 1024; z++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=1024

        if (z >= max_iter_val) {
            last_z = z;
            break;
        }
        last_z = z;

        // ── Find (p, q) with largest |A[i,j]|, i < j ─────────────────
        fx_t off_diag_max = fx_t(0);
        int p = 0, q = 1;

        FIND_PQ_I:
        for (int i = 0; i < N; i++) {
            FIND_PQ_J:
            for (int j = i + 1; j < N; j++) {
#pragma HLS PIPELINE II=1
                fx_t mag = cx_abs(A_buf[i][j].re, A_buf[i][j].im);
                if (mag > off_diag_max) {
                    off_diag_max = mag;
                    p = i;
                    q = j;
                }
            }
        }

        // ── Convergence check  (1e-8 → use 2^-23 ≈ 1.19e-7 as threshold)
        if (off_diag_max < fx_t(0.0000001)) {
            break;
        }

        // ── Compute rotation parameters ───────────────────────────────
        cx_t a_pp = A_buf[p][p];
        cx_t a_qq = A_buf[q][q];
        cx_t a_pq = A_buf[p][q];

        fx_t a_pq_abs = cx_abs(a_pq.re, a_pq.im);

        // theta = 0.5 * atan( 2|a_pq| / (a_pp.re - a_qq.re) )
        // (diagonal entries are real after each sweep)
        fx_t denom  = a_pp.re - a_qq.re;
        fx_t numer  = fx_t(2) * a_pq_abs;
        fx_t angle_arg = fx_atan2(numer, denom);
        fx_t theta  = angle_arg >> 1;   // * 0.5

        // phi = -angle(a_pq) = -atan2(im, re)
        fx_t phi = -fx_atan2(a_pq.im, a_pq.re);

        fx_t cos_theta, sin_theta;
        fx_cos_sin(theta, cos_theta, sin_theta);

        fx_t cos_phi, sin_phi;
        fx_cos_sin(phi, cos_phi, sin_phi);

        // e^{-i*phi} = cos(phi) - i*sin(phi)  [phi already negated above]
        // U[p,q] = sin(theta) * e^{-i*phi}
        // U[q,p] = sin(theta) * e^{+i*phi}  (= conj of U[p,q])
        // U[p,p] =  cos(theta)  (real)
        // U[q,q] = -cos(theta)  (real, note sign in Python)

        cx_t U_pp, U_qq, U_pq, U_qp;
        U_pp.re =  cos_theta; U_pp.im = fx_t(0);
        U_qq.re = -cos_theta; U_qq.im = fx_t(0);
        // e^{-i*phi}: cos_phi is cos(-phi)=cos(phi), sin part uses phi already negated
        U_pq.re = sin_theta * cos_phi;
        U_pq.im = sin_theta * (-sin_phi);  // e^{-i*phi}
        U_qp.re = sin_theta * cos_phi;
        U_qp.im = sin_theta * sin_phi;     // e^{+i*phi}

        // ── Compute A' = U^H * A * U ──────────────────────────────────
        // Step 1: tmp1 = U^H * A
        // U^H[r,s] is conjugate-transpose of U[s,r].
        // U is mostly identity except rows/cols p and q.
        //
        // For row k != p and k != q: (U^H)[k,:] = e_k → tmp1[k,:] = A[k,:]
        // For row p: (U^H)[p,p]=conj(U_pp)=U_pp (real), (U^H)[p,q]=conj(U_qp)
        // For row q: (U^H)[q,p]=conj(U_pq),           (U^H)[q,q]=conj(U_qq)=U_qq (real)

        COPY_TMP1:
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            for (int j = 0; j < N; j++) {
                tmp1[i][j] = A_buf[i][j];
            }
        }

        // Update rows p and q of tmp1
        ROW_PQ_J:
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            cx_t Ap_j = A_buf[p][j];
            cx_t Aq_j = A_buf[q][j];

            // conj(U_pp) = U_pp (real), conj(U_qp) is conj of U[q,p]
            cx_t cU_pp = cx_conj(U_pp);   // = U_pp
            cx_t cU_qp = cx_conj(U_qp);   // = conj(U[q,p])
            cx_t cU_pq = cx_conj(U_pq);
            cx_t cU_qq = cx_conj(U_qq);   // = U_qq (real)

            // tmp1[p][j] = cU_pp * A[p][j] + cU_qp * A[q][j]
            tmp1[p][j] = cx_add(cx_mul(cU_pp, Ap_j), cx_mul(cU_qp, Aq_j));
            // tmp1[q][j] = cU_pq * A[p][j] + cU_qq * A[q][j]
            tmp1[q][j] = cx_add(cx_mul(cU_pq, Ap_j), cx_mul(cU_qq, Aq_j));
        }

        // Step 2: tmp2 = tmp1 * U
        // U is mostly identity except cols p and q.
        // For col k != p, k != q: U[:,k] = e_k → tmp2[:,k] = tmp1[:,k]
        // For col p: U[p,p]=U_pp, U[q,p]=U_qp, rest zero
        // For col q: U[p,q]=U_pq, U[q,q]=U_qq, rest zero

        COPY_TMP2:
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            for (int j = 0; j < N; j++) {
                tmp2[i][j] = tmp1[i][j];
            }
        }

        COL_PQ_I:
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            cx_t Ti_p = tmp1[i][p];
            cx_t Ti_q = tmp1[i][q];

            // tmp2[i][p] = Ti_p * U_pp + Ti_q * U_qp
            tmp2[i][p] = cx_add(cx_mul(Ti_p, U_pp), cx_mul(Ti_q, U_qp));
            // tmp2[i][q] = Ti_p * U_pq + Ti_q * U_qq
            tmp2[i][q] = cx_add(cx_mul(Ti_p, U_pq), cx_mul(Ti_q, U_qq));
        }

        // Force (p,q) and (q,p) to zero explicitly
        tmp2[p][q].re = fx_t(0); tmp2[p][q].im = fx_t(0);
        tmp2[q][p].re = fx_t(0); tmp2[q][p].im = fx_t(0);

        // Write back to A_buf
        WB_A:
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            for (int j = 0; j < N; j++) {
                A_buf[i][j] = tmp2[i][j];
            }
        }

        // ── Update V' = V * U ─────────────────────────────────────────
        // Only columns p and q change.
        COPY_TMP3:
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            for (int j = 0; j < N; j++) {
                tmp3[i][j] = V_buf[i][j];
            }
        }

        UPDATE_V_I:
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            cx_t Vi_p = V_buf[i][p];
            cx_t Vi_q = V_buf[i][q];

            // tmp3[i][p] = Vi_p * U_pp + Vi_q * U_qp
            tmp3[i][p] = cx_add(cx_mul(Vi_p, U_pp), cx_mul(Vi_q, U_qp));
            // tmp3[i][q] = Vi_p * U_pq + Vi_q * U_qq
            tmp3[i][q] = cx_add(cx_mul(Vi_p, U_pq), cx_mul(Vi_q, U_qq));
        }

        WB_V:
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            for (int j = 0; j < N; j++) {
                V_buf[i][j] = tmp3[i][j];
            }
        }
    } // end JACOBI_LOOP

    // ── Copy results to outputs ───────────────────────────────────────────
    COPY_EIGENVALUES:
    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        out0[i].re = (out0_scalar_t)A_buf[i][i].re;
        out0[i].im = (out0_scalar_t)A_buf[i][i].im;
    }

    COPY_EIGENVECTORS:
    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            out1[i][j].re = (out1_scalar_t)V_buf[i][j].re;
            out1[i][j].im = (out1_scalar_t)V_buf[i][j].im;
        }
    }

    *out2 = (out2_t)last_z;
}
